const modelle: QTuple[] = [
  [1, "Welche Pflegetheoretikerin ist für die 12 „Aktivitäten, Beziehungen und existenziellen Erfahrungen des Lebens“ (ABEDL) bekannt?|أي منظّرة تمريض اشتهرت بـ«أنشطة الحياة» (ABEDL)؟", ["Monika Krohwinkel", "Florence Nightingale", "Dorothea Orem", "Hildegard Peplau"], 0, "Krohwinkels Modell (ABEDL) beschreibt 13 Bereiche des Lebens (u. a. Kommunizieren, Sich bewegen, Essen und Trinken, Sinn finden) und prägt die Pflegeplanung in Deutschland. Das AEDL-Modell wurde zu ABEDL erweitert.|نموذج كروهفينكل (ABEDL) يصف 13 مجالًا للحياة (منها التواصل والحركة والأكل والشرب وإيجاد المعنى) وله تأثير كبير على التخطيط التمريضي في ألمانيا."],
  [1, "Worum geht es bei Orems Selbstpflegedefizit-Theorie?|ما موضوع نظرية عجز الرعاية الذاتية عند أوريم؟", ["Pflege tritt ein, wenn Menschen ihre Selbstpflege nicht selbst leisten können", "Pflege ersetzt immer jede Eigenleistung", "Pflege gilt nur für Kinder", "Pflege ist ausschließlich Aufgabe der Ärzte"], 0, "Orem unterscheidet Selbstpflege, Selbstpflegedefizit und Pflegesysteme (vollständig kompensatorisch, teilweise kompensatorisch, unterstützend-edukativ). Ziel: Selbstständigkeit fördern.|تميز أوريم بين الرعاية الذاتية والعجز ونظم الرعاية (تعويضي كامل وجزئي وداعم-تثقيفي). الهدف تعزيز الاستقلالية."],
  [1, "Wofür ist Florence Nightingale vor allem bekannt?|بماذا اشتهرت فلورنس نايتنغيل؟", ["Hygiene, Umgebung und statistische Pflegequalität, Begründerin der modernen Krankenpflege", "Entwicklung des Penicillins", "Erfindung der Narkose", "Begründung der Psychoanalyse"], 0, "Nightingale (1820–1910) verbesserte im Krimkrieg Hygiene und Sterblichkeit, nutzte Statistik und gilt als Begründerin der modernen Pflege; ihr Umweltmodell sieht Licht, Luft, Ruhe, Sauberkeit als Heilfaktoren.|حسّنت نايتنغيل النظافة وخفضت الوفيات في حرب القرم واستخدمت الإحصاء وتُعتبر مؤسسة التمريض الحديث؛ نموذجها البيئي يرى الضوء والهواء والهدوء والنظافة عوامل شفاء."],
  [1, "Welche Aussage zu Pflegetheorien ist zutreffend?|أي عبارة عن نظريات التمريض صحيحة؟", ["Sie liefern Denkrahmen zur Begründung und Strukturierung pflegerischen Handelns", "Sie sind Gesetze", "Sie ersetzen die Praxis", "Sie sind nur für Ärzte"], 0, "Pflegetheorien/-modelle ordnen Wissen, begründen Entscheidungen und leiten die Pflegeplanung; verschiedene Modelle betonen unterschiedliche Aspekte (Bedürfnisse, Selbstpflege, Beziehung, Anpassung).|توفر أطر تفكير لتعليل وتنظيم الممارسة التمريضية؛ وتركز النماذج على جوانب مختلفة (احتياجات ورعاية ذاتية وعلاقة وتكيف)."],
  [2, "Welche Stufen beschreibt Maslow in seiner Bedürfnispyramide von unten nach oben?|ما درجات هرم ماسلو من الأسفل للأعلى؟", ["Physiologisch, Sicherheit, Zugehörigkeit, Wertschätzung, Selbstverwirklichung", "Selbstverwirklichung, Sicherheit, Zugehörigkeit, Essen, Wertschätzung", "Zugehörigkeit, Wertschätzung, Essen, Sicherheit, Selbstverwirklichung", "Sicherheit, Essen, Selbstverwirklichung, Zugehörigkeit, Wertschätzung"], 0, "Grundbedürfnisse (Atmung, Nahrung, Schlaf) müssen weitgehend befriedigt sein, bevor höhere Bedürfnisse (soziale Bindung, Anerkennung, Selbstverwirklichung) handlungsleitend werden. In der Pflege dient das Modell zur Priorisierung.|يجب إشباع الحاجات الأساسية (تنفس وغذاء ونوم) نسبيًا قبل أن تصبح الحاجات الأعلى (انتماء وتقدير وتحقيق الذات) محركة. يُستخدم في التمريض لترتيب الأولويات."],
  [2, "Wofür steht Peplaus Modell der interpersonellen Beziehung?|ما الذي يركز عليه نموذج بيبلاو للعلاقة بين الأشخاص؟", ["Pflege als therapeutische zwischenmenschliche Beziehung mit Phasen (Orientierung, Identifikation, Nutzung, Ablösung)", "Hygiene", "Dokumentation", "Berufsrecht"], 0, "Hildegard Peplau beschreibt Pflege als Prozess in Beziehung: Orientierung, Identifikation, Nutzung, Ablösung; Pflegende nehmen Rollen ein (Fremde, Beraterin, Lehrende …). Besonders relevant in Psychiatrie und Beratung.|تصف هيلدغارد بيبلاو التمريض كعملية في علاقة: توجّه وتعرّف واستفادة وانفصال، ويتخذ الممرض أدوارًا (غريب ومستشار ومعلّم …). مهم خاصة في الطب النفسي والإرشاد."],
  [2, "Was beschreibt Roper-Logan-Tierney?|ماذا يصف نموذج روبر-لوغان-تيرني؟", ["Lebensaktivitäten (z. B. Atmen, Essen, Ausscheiden) im Lebenslauf und die Abhängigkeits-/Unabhängigkeits-Kontinuum", "Nur Medikamentenlehre", "Berufsrecht", "Hygieneplan"], 0, "Das Modell beschreibt 12 Lebensaktivitäten, beeinflusst von biologischen, psychologischen, soziokulturellen, umweltbezogenen und politisch-ökonomischen Faktoren, und ordnet Personen auf einem Kontinuum zwischen Abhängigkeit und Unabhängigkeit ein.|يصف 12 نشاطًا حياتيًا تتأثر بعوامل حيوية ونفسية واجتماعية ثقافية وبيئية وسياسية-اقتصادية ويضع الشخص على سلسلة بين الاعتماد والاستقلال."],
  [2, "Welche Rolle hat das Konzept des „Salutogenese“-Modells in der Pflege?|ما دور نموذج «التكوّن الصحي» (Salutogenese) في التمريض؟", ["Fokus auf Ressourcen und Gesundheitserhaltung statt nur auf Krankheit; Kohärenzgefühl", "Fokus nur auf Krankheitsursachen", "Ablehnung von Prävention", "Reine Technikbetonung"], 0, "Antonovskys Salutogenese fragt: Was hält Menschen gesund? Kohärenzgefühl (Verstehbarkeit, Handhabbarkeit, Bedeutsamkeit) und Ressourcen stärken Gesundheit; Pflege fördert Ressourcen und Bewältigung (Coping).|يسأل أنطونوفسكي: ما الذي يُبقي الناس أصحاء؟ الإحساس بالتماسك (قابلية الفهم والإدارة والمعنى) والموارد يقويان الصحة؛ والتمريض يعزز الموارد والتأقلم."],
  [3, "Eine Pflegekraft wählt für einen Patienten mit Schlaganfall einen Ansatz, der seine Selbstständigkeit maximal fördert. Welches Modell passt am besten?|ممرضة تختار لمريض سكتة نهجًا يعزز استقلاليته إلى أقصى حد. أي نموذج الأنسب؟", ["Orems Selbstpflegedefizit-Theorie (unterstützend-edukatives System)", "Reine Funktionspflege", "Ausschließlich Fürsorge ohne Beteiligung", "Rein biomedizinisches Modell"], 0, "Die Orem-Theorie unterscheidet nach Selbstpflegefähigkeit; bei teilweisem Defizit wird unterstützt und angeleitet, damit der Patient so viel wie möglich selbst tun kann. Passt zur aktivierenden Pflege und Rehabilitation.|تميز نظرية أوريم بحسب القدرة على الرعاية الذاتية؛ عند العجز الجزئي يُدعم ويُوجَّه المريض ليفعل أكثر ما يمكن بنفسه. تناسب التمريض المنشِّط والتأهيل."],
  [3, "Welche Kritik wird häufig an Bedürfnismodellen geäußert?|ما النقد الشائع لنماذج الحاجات؟", ["Gefahr einer defizitorientierten Sicht und zu starken Standardisierung; individuelle Situation und Kultur können zu kurz kommen", "Sie sind zu individuell", "Sie berücksichtigen Bedürfnisse zu stark", "Sie sind zu aktuell"], 0, "Bedürfnismodelle sind hilfreich zur Strukturierung, können aber Menschen auf Defizite reduzieren. Ergänzend sind Ressourcenorientierung, biografische Aspekte und Beziehungsgestaltung wichtig.|تساعد نماذج الحاجات في التنظيم لكنها قد تختزل الإنسان في النواقص. من المهم إضافة التركيز على الموارد والجوانب السيرية وبناء العلاقة."],
  [3, "Was bedeutet „Primary Nursing“ im Gegensatz zur Funktionspflege?|ماذا يعني «Primary Nursing» مقابل التمريض الوظيفي؟", ["Eine Pflegefachperson trägt kontinuierlich die Verantwortung für den gesamten Pflegeprozess einer kleinen Patientengruppe", "Jede Pflegekraft macht nur eine Aufgabe für alle Patienten", "Keine Planung", "Nur Nachtdienst"], 0, "Primary Nursing: Bezugspflegende planen, steuern und evaluieren die Pflege über den gesamten Aufenthalt, Beziehungskontinuität, Verantwortlichkeit und Zufriedenheit steigen. Funktionspflege ist aufgabenorientiert und fragmentiert.|في Primary Nursing تتولى ممرضة مرجعية التخطيط والتنفيذ والتقييم لكل الإقامة فتزيد الاستمرارية والمسؤولية والرضا. أما الوظيفي فموجّه بالمهام ومجزأ."],
];

